// Existing using directives...\nusing System.Collections.ObjectModel;\nusing System.Windows.Input;\n\npublic class CoursesViewModel\n{\n    // Existing properties...\n\n    // New properties for keyword search\n    public ObservableCollection<string> SearchKeywords { get; set; } = new ObservableCollection<string>();\n    public string KeywordInput { get; set; }\n    public bool IsFromInterest { get; set; } = true;\n    private string _categoryText;\n\n    public ICommand AddKeywordCommand { get; }\n    public ICommand RemoveKeywordCommand { get; }\n\n    public CoursesViewModel()\n    {\n        // Existing constructor code...\n\n        // Initialize new commands\n        AddKeywordCommand = new RelayCommand(AddKeyword);\n        RemoveKeywordCommand = new RelayCommand(RemoveKeyword);\n    }\n\n    // Existing methods...\n\n    public void AddKeyword()\n    {\n        if (!string.IsNullOrWhiteSpace(KeywordInput) && !SearchKeywords.Contains(KeywordInput))\n        {\n            SearchKeywords.Add(KeywordInput);\n            KeywordInput = string.Empty; // Clear input after adding\n        }\n    }\n\n    public void RemoveKeyword(string keyword)\n    {\n        if (SearchKeywords.Contains(keyword))\n        {\n            SearchKeywords.Remove(keyword);\n        }\n    }\n\n    // Existing method...\n    private async Task InitAsync()\n    {\n        // Existing initialization code...\n\n        _categoryText = // logic to store category text\n    }\n\n    private async Task SearchByKeywordsAsync()\n    {\n        var matchingCourses = new List<CourseItem>();\n\n        foreach (var keyword in SearchKeywords)\n        {\n            // Use InterestAnalyzer to match keywords\n            var coursesForKeyword = await InterestAnalyzer.FetchCoursesForKeyword(keyword);\n            matchingCourses.AddRange(coursesForKeyword);\n        }\n\n        // Deduplicate results using CourseItemComparer\n        var distinctCourses = matchingCourses.Distinct(new CourseItemComparer()).ToList();\n\n        // Apply filters\n        var filteredCourses = distinctCourses.Where(course => \n            course.Title.Contains(string.Join(" ", SearchKeywords), StringComparison.OrdinalIgnoreCase) &&\n            // Additional filters like Where/Day/Time\n        ).ToList();\n\n        IsFromInterest = false;\n        // Logic to update the displayed courses...\n    }\n\n    // Existing methods...\n\n    private class CourseItemComparer : IEqualityComparer<CourseItem>\n    {\n        public bool Equals(CourseItem x, CourseItem y)\n        {\n            return x.Id == y.Id; // Assuming CourseItem has an Id property\n        }\n\n        public int GetHashCode(CourseItem obj)\n        {\n            return obj.Id.GetHashCode();\n        }\n    }\n}